def uygula(apps, schema_editor):
    """Rulo malzemeler 'eskisine eklensin' işaretlenir; fasondan gelen miktar ayrı yazılır; bu türlerde aynı
    tür + renk + model + firma kayıtları tek kayıtta birleşir (eski etiket numaraları gelişte kalır)."""
    M = {ad: apps.get_model("uretim", ad) for ad in
         ("DeriTuru", "HamDeriGirisi", "StokGelisi", "LotKaynagi", "DeriDuzeltme", "FasonIsi", "IslemKaydi")}
    for tur in M["DeriTuru"].objects.all():
        if stok_birlestir.toplu_ad_mi(tur.ad, tur.bilesik):
            tur.toplu = True
            tur.save(update_fields=["toplu"])
    for f in M["FasonIsi"].objects.filter(gelen_lot__isnull=False, gelen_m2__isnull=True):
        f.gelen_m2 = M["HamDeriGirisi"].objects.get(pk=f.gelen_lot_id).m2
        f.save(update_fields=["gelen_m2"])
    stok_birlestir.birlestir(M)


